package br.com.admeclesial.domain.pessoa; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID; @Entity @Table(name="familia",schema="adm_eclesial") public class Familia { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(nullable=false,length=200) String nome; @Column(nullable=false) boolean ativo=true; @Column(name="data_cadastro",nullable=false,updatable=false) LocalDateTime dataCadastro; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();if(dataCadastro==null)dataCadastro=LocalDateTime.now();} public Long getId(){return id;}public UUID getUuid(){return uuid;}public String getNome(){return nome;}public boolean isAtivo(){return ativo;}public LocalDateTime getDataCadastro(){return dataCadastro;}public void setNome(String v){nome=v;}public void setAtivo(boolean v){ativo=v;} }